function sqlSelect(rows, columns, where) {
  var filtered = where ? rows.filter(where) : rows;
  if (columns[0] === '*') return filtered;
  return filtered.map(function(row) {
    var result = {};
    columns.forEach(function(col) { result[col] = row[col]; });
    return result;
  });
}

function sqlOrderLimit(rows, sortKey, direction, limit, offset) {
  var sorted = rows.slice().sort(function(a, b) {
    if (a[sortKey] < b[sortKey]) return direction === 'ASC' ? -1 : 1;
    if (a[sortKey] > b[sortKey]) return direction === 'ASC' ? 1 : -1;
    return 0;
  });
  return sorted.slice(offset, offset + limit);
}

function innerJoin(tableA, tableB, keyA, keyB) {
  var result = [];
  tableA.forEach(function(rowA) {
    tableB.forEach(function(rowB) {
      if (rowA[keyA] === rowB[keyB]) {
        var merged = {};
        Object.keys(rowA).forEach(function(k) { merged[k] = rowA[k]; });
        Object.keys(rowB).forEach(function(k) { merged[k] = rowB[k]; });
        result.push(merged);
      }
    });
  });
  return result;
}

function groupByAgg(rows, groupKey, valueKey, aggFn) {
  var groups = {};
  rows.forEach(function(row) {
    var key = row[groupKey];
    if (!groups[key]) groups[key] = [];
    groups[key].push(row[valueKey]);
  });
  return Object.keys(groups).sort().map(function(key) {
    return { group: key, aggregate: aggFn(groups[key]) };
  });
}
